theorem hasDerivAt_ext (g : (ι → Bool) → ℝ) {c : ℝ → ι → ℝ} {c' : ι → ℝ} {t : ℝ}
    (hc : ∀ a, HasDerivAt (fun s => c s a) (c' a) t) :
    HasDerivAt (fun s => ext g (c s)) (∑ a, c' a * ext (D a g) (c t)) t

