theorem integral_reflect (e : ι → ℝ) (he : ∑ i, e i ^ 2 = 1) {F : (ι → ℝ) → ℝ}
    (hF : Measurable F) :
    ∫ u, F (fun i => u i - 2 * (∑ j, e j * u j) * e i) ∂(gP ι) = ∫ u, F u ∂(gP ι)

